create extension if not exists pgcrypto;
create table if not exists exercises(id uuid primary key default gen_random_uuid(),day_no int not null,sort_order int not null,name text not null,increment_kg numeric(6,2) default 2.5,default_weight numeric(6,2) default 0,active boolean default true);
create table if not exists workouts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,workout_day int not null,performed_at timestamptz default now());
create table if not exists workout_sets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,workout_id uuid not null references workouts(id) on delete cascade,exercise_id uuid not null references exercises(id),set_no int not null,weight_kg numeric(6,2) default 0,reps int default 0,created_at timestamptz default now());
alter table exercises enable row level security; alter table workouts enable row level security; alter table workout_sets enable row level security;
create policy "read exercises" on exercises for select to authenticated using(true);
create policy "own workouts" on workouts for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own sets" on workout_sets for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
